#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Projectiles
{
    [AutoBuffDefinition(VanillaBuffNames.Projectile.chillProjectile)]
    public class ChillProjectileBuff : BuffDefinition
    {
        public ChillProjectileBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(VanillaEntityProps.IS_FROST, true));
            AddModifier(new NamespaceIDArrayModifier(VanillaProjectileProps.DAMAGE_EFFECTS, ArrayOperator.Union, new NamespaceID[] { VanillaDamageEffects.SLOW }));
        }
    }
}
